import{_ as n,o as s,c as e,a2 as l}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"持久执行与恢复","description":"Hearth Durable Harness 的 Run 生命周期、任务图、lease、恢复策略、路由与 MVP 关系。","frontmatter":{"title":"持久执行与恢复","description":"Hearth Durable Harness 的 Run 生命周期、任务图、lease、恢复策略、路由与 MVP 关系。","outline":[2,3]},"headers":[],"relativePath":"architecture/durable-execution.md","filePath":"architecture/durable-execution.md","lastUpdated":1793706118000}'),t={name:"architecture/durable-execution.md"};function i(p,a,r,o,c,d){return s(),e("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">DURABLE HARNESS</p><h1 id="持久执行与恢复" tabindex="-1">持久执行与恢复 <a class="header-anchor" href="#持久执行与恢复" aria-label="Permalink to &quot;持久执行与恢复&quot;">​</a></h1><p class="lead">长任务必须跨崩溃、休眠、网络中断和执行器失败继续存在。Durable Harness 负责把意图变成可恢复的执行。</p><h2 id="durable-harness" tabindex="-1">Durable Harness <a class="header-anchor" href="#durable-harness" aria-label="Permalink to &quot;Durable Harness&quot;">​</a></h2><p>Harness 是“把一次意图变成可恢复执行”的中间层：</p><ul><li>承接 Control Plane 的决策；</li><li>构建任务图；</li><li>选择执行器；</li><li>执行预算和 lease；</li><li>处理取消、重试、恢复；</li><li>把结果转成 Artifact、Receipt 和 Eval。</li></ul><p>它不是模型，也不是 Sandbox。</p><h3 id="run-生命周期" tabindex="-1">Run 生命周期 <a class="header-anchor" href="#run-生命周期" aria-label="Permalink to &quot;Run 生命周期&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>created</span></span>
<span class="line"><span>  → authorized</span></span>
<span class="line"><span>  → queued</span></span>
<span class="line"><span>  → assigned</span></span>
<span class="line"><span>  → running</span></span>
<span class="line"><span>  → verifying</span></span>
<span class="line"><span>  → completed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>异常分支：</span></span>
<span class="line"><span>  → paused</span></span>
<span class="line"><span>  → waiting_approval</span></span>
<span class="line"><span>  → waiting_input</span></span>
<span class="line"><span>  → retry_wait</span></span>
<span class="line"><span>  → failed</span></span>
<span class="line"><span>  → cancelled</span></span>
<span class="line"><span>  → needs_human</span></span></code></pre></div><p>每个状态迁移必须：</p><ul><li>产生事件；</li><li>有明确触发者；</li><li>有幂等条件；</li><li>可以从事件重放；</li><li>不允许原地覆盖历史。</li></ul><h3 id="任务图" tabindex="-1">任务图 <a class="header-anchor" href="#任务图" aria-label="Permalink to &quot;任务图&quot;">​</a></h3><p>支持顺序依赖、并行分支、汇合、失败传播、补偿任务、人工审批节点、跨天等待、长任务检查点和子任务预算继承。</p><p>第一阶段不引入重型工作流引擎，使用显式状态机、SQLite、outbox、定时器和 lease，加上清晰的中间产物。</p><h3 id="lease-与单写者" tabindex="-1">Lease 与单写者 <a class="header-anchor" href="#lease-与单写者" aria-label="Permalink to &quot;Lease 与单写者&quot;">​</a></h3><ul><li>每个 Ticket 同一时刻最多一个有效 Assignment；</li><li>Executor 或设备必须持有 lease 才能推进；</li><li>lease 过期后可重新分配；</li><li>重新分配必须带 fencing token，拒绝旧执行者继续写入；</li><li>同一 State Root 只有一个写权威；</li><li>设备本地状态只是缓存；</li><li>设备离线时任务排队，重新上线按 cursor、lease 和检查点继续；</li><li>设备丢失必须撤销 lease、capability 和密钥。</li></ul><h3 id="恢复策略" tabindex="-1">恢复策略 <a class="header-anchor" href="#恢复策略" aria-label="Permalink to &quot;恢复策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>故障</th><th>恢复方式</th></tr></thead><tbody><tr><td>进程崩溃</td><td>从 Event Log 和检查点恢复</td></tr><tr><td>网络中断</td><td>保留 outbox；恢复后按幂等键重投</td></tr><tr><td>Executor 超时</td><td>保存 workspace 快照；重试或换 Executor</td></tr><tr><td>设备离线</td><td>进入设备队列；不丢任务</td></tr><tr><td>外部结果不确定</td><td>标记 uncertain；先对账，不盲目重试</td></tr><tr><td>记忆冲突</td><td>保留来源；不静默覆盖</td></tr></tbody></table><p>恢复后必须重新验证，不信任旧的自然语言“完成”。</p><h3 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to &quot;路由&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ticket</span></span>
<span class="line"><span>  → 能力匹配</span></span>
<span class="line"><span>  → 风险与权限检查</span></span>
<span class="line"><span>  → Token / 成本 / 延迟估计</span></span>
<span class="line"><span>  → 选择 Executor 或 Human</span></span>
<span class="line"><span>  → 执行</span></span>
<span class="line"><span>  → 验证失败？</span></span>
<span class="line"><span>      ├─ 同 Executor 重试</span></span>
<span class="line"><span>      ├─ 换更合适的 Executor</span></span>
<span class="line"><span>      ├─ 降级为更小范围</span></span>
<span class="line"><span>      └─ 人工接管</span></span></code></pre></div><p>路由不应只由模型决定。规则、历史成功率、成本、权限和设备状态都参与。</p><h3 id="边界规则" tabindex="-1">边界规则 <a class="header-anchor" href="#边界规则" aria-label="Permalink to &quot;边界规则&quot;">​</a></h3><ol><li>Control Plane 不直接执行工具。</li><li>Harness 不直接读取原始凭据。</li><li>Executor 不决定“是否允许”。</li><li>Execution Gateway 不决定业务意图。</li><li>UI 不能绕过 Policy 写数据库或触发工具。</li><li>所有外部副作用经过 outbox、幂等键和 Receipt。</li><li>所有 schema 变更带 migration 和兼容测试。</li></ol><h2 id="与-mvp-的关系" tabindex="-1">与 MVP 的关系 <a class="header-anchor" href="#与-mvp-的关系" aria-label="Permalink to &quot;与 MVP 的关系&quot;">​</a></h2><p>MVP 不需要完整实现 Gateway、Trigger、设备目录和所有恢复策略，但必须具备最小真实链路：</p><ul><li>Web 输入进入 Gateway → Event；</li><li>Control Plane 创建 Task/Ticket；</li><li>Harness 持久化 Run 和状态；</li><li>Codex 执行并产生事件；</li><li>验证器决定完成；</li><li>Web 从投影展示任务卡和恢复入口。</li></ul><p>没有这条链路，就不是 MVP，只是前端演示或后端库。</p>`,28)])])}const b=n(t,[["render",i]]);export{h as __pageData,b as default};
